import React, { useEffect, useState } from "react";
import { createUser, getFranchises } from "../api";
import {
    Box,
    Typography,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow,
    Paper,
    Button,
    TextField,
    Modal,
} from "@mui/material";

const AdminDashboard = () => {
    const [franchises, setFranchises] = useState([]);
    const [open, setOpen] = useState(false); // Modal state
    const [newUser, setNewUser] = useState({
        username: "",
        password: "",
        name: "",
        role: "user",
        franchiseId: "",
    });

    // Fetch franchises
    useEffect(() => {
        const fetchFranchises = async () => {
            try {
                const data = await getFranchises();
                setFranchises(data);
            } catch (error) {
                console.error("Error fetching franchises:", error.response?.data?.message || error.message);
            }
        };

        fetchFranchises();
    }, []);

    // Handle form input change
    const handleChange = (e) => {
        const { name, value } = e.target;
        setNewUser((prev) => ({ ...prev, [name]: value }));
    };

    // Handle create user form submission
    const handleCreateUser = async () => {
        try {
            await createUser(newUser);
            alert("User created successfully");
            setOpen(false);
        } catch (error) {
            console.error("Error creating user:", error.response?.data?.message || error.message);
        }
    };

    return (
        <Box p={3}>
            <Typography variant="h4" gutterBottom>
                Admin Dashboard
            </Typography>

            {/* Franchises Table */}
            <TableContainer component={Paper}>
                <Table>
                    <TableHead>
                        <TableRow>
                            <TableCell>Franchise Name</TableCell>
                            <TableCell>Location</TableCell>
                            <TableCell>Status</TableCell>
                            <TableCell>Actions</TableCell>
                        </TableRow>
                    </TableHead>
                    <TableBody>
                        {franchises.map((franchise) => (
                            <TableRow key={franchise._id}>
                                <TableCell>{franchise.name}</TableCell>
                                <TableCell>{franchise.location}</TableCell>
                                <TableCell>{franchise.status}</TableCell>
                                <TableCell>
                                    <Button
                                        variant="contained"
                                        color="primary"
                                        onClick={() => setNewUser((prev) => ({ ...prev, franchiseId: franchise._id })) || setOpen(true)}
                                    >
                                        Add User
                                    </Button>
                                </TableCell>
                            </TableRow>
                        ))}
                    </TableBody>
                </Table>
            </TableContainer>

            {/* Modal for creating user */}
            <Modal open={open} onClose={() => setOpen(false)}>
                <Box
                    sx={{
                        position: "absolute",
                        top: "50%",
                        left: "50%",
                        transform: "translate(-50%, -50%)",
                        width: 400,
                        bgcolor: "background.paper",
                        borderRadius: 2,
                        boxShadow: 24,
                        p: 4,
                    }}
                >
                    <Typography variant="h6" gutterBottom>
                        Create User
                    </Typography>
                    <TextField
                        label="Username"
                        name="username"
                        value={newUser.username}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                    />
                    <TextField
                        label="Password"
                        name="password"
                        type="password"
                        value={newUser.password}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                    />
                    <TextField
                        label="Name"
                        name="name"
                        value={newUser.name}
                        onChange={handleChange}
                        fullWidth
                        margin="normal"
                    />
                    <Button variant="contained" color="primary" onClick={handleCreateUser}>
                        Submit
                    </Button>
                </Box>
            </Modal>
        </Box>
    );
};

export default AdminDashboard;
